import { NextRequest, NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createPayment, PRODUCTS, type EditaProduct } from "@/lib/yookassa";
import { getSupabaseServiceClient, getUserFromAccessToken } from "@/lib/server-supabase";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const product = body?.product as EditaProduct;
    if (!PRODUCTS[product]) return NextResponse.json({ error: "Unknown product" }, { status: 400 });

    const bearer=req.headers.get("authorization");
    const accessToken=bearer?.startsWith("Bearer ")?bearer.slice(7):null;
    const user=await getUserFromAccessToken(accessToken);

    if(!user){
      return NextResponse.json({error:"Войди в EDITA перед оплатой, чтобы доступ привязался к твоему аккаунту."},{status:401});
    }

    const service=getSupabaseServiceClient();
    if(service){
      const {data:profile}=await service.from("profiles")
        .select("onboarding,guardian_verified")
        .eq("id",user.id).maybeSingle();
      const ageGroup=profile?.onboarding?.ageGroup||"18+";
      if(ageGroup!=="18+"&&!profile?.guardian_verified){
        return NextResponse.json({error:"Для оплаты пользователю младше 18 лет сначала нужно подтверждение родителя или законного представителя."},{status:403});
      }
    }

    const customerEmail=user?.email||
      (typeof body?.email==="string"&&body.email.includes("@")?body.email.trim():undefined);
    const siteUrl=process.env.NEXT_PUBLIC_SITE_URL||req.nextUrl.origin;

    const {data,orderId}=await createPayment({
      product,
      customerEmail,
      userId:user?.id,
      returnUrl:siteUrl+"/payment/return",
    });

    const confirmationUrl=data?.confirmation?.confirmation_url;
    if(!data?.id||!confirmationUrl){
      return NextResponse.json({error:"YooKassa did not return confirmation URL"},{status:502});
    }

    const cookieStore=await cookies();
    cookieStore.set("edita_last_payment_id",data.id,{httpOnly:true,secure:true,sameSite:"lax",maxAge:60*60*2,path:"/"});
    cookieStore.set("edita_last_product",product,{httpOnly:true,secure:true,sameSite:"lax",maxAge:60*60*2,path:"/"});

    return NextResponse.json({paymentId:data.id,orderId,confirmationUrl});
  } catch(error) {
    console.error("YooKassa create payment error",error);
    return NextResponse.json({error:error instanceof Error?error.message:"Payment creation failed"},{status:502});
  }
}

import {NextResponse} from "next/server";
import {getYooKassaConfig,yookassaRequest} from "@/lib/yookassa";

export async function GET(){
  const configured=Boolean(getYooKassaConfig());
  const mode=process.env.YOOKASSA_MODE||"test";
  if(!configured)return NextResponse.json({configured:false,connected:false,mode});
  try{
    const data=await yookassaRequest("/payments?limit=1",{method:"GET"});
    return NextResponse.json({configured:true,connected:true,mode,count:Array.isArray(data?.items)?data.items.length:0});
  }catch(error){
    return NextResponse.json({configured:true,connected:false,mode,error:error instanceof Error?error.message:"YooKassa API error"});
  }
}

import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { PRODUCTS, yookassaRequest, type EditaProduct } from "@/lib/yookassa";

export async function GET() {
  try {
    const cookieStore = await cookies();
    const paymentId = cookieStore.get("edita_last_payment_id")?.value;
    const product = cookieStore.get("edita_last_product")?.value as EditaProduct | undefined;

    if (!paymentId) {
      return NextResponse.json({ error: "No payment session" }, { status: 404 });
    }

    const payment = await yookassaRequest("/payments/" + encodeURIComponent(paymentId));
    const productInfo = product && PRODUCTS[product] ? PRODUCTS[product] : null;

    return NextResponse.json({
      id: payment.id,
      status: payment.status,
      paid: Boolean(payment.paid),
      amount: payment.amount,
      product: product || payment.metadata?.product || null,
      productName: productInfo?.name || payment.description || null,
      test: Boolean(payment.test),
    });
  } catch (error) {
    console.error("YooKassa payment status error", error);
    return NextResponse.json({ error: "Could not verify payment" }, { status: 502 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { yookassaRequest } from "@/lib/yookassa";
import { grantPaidAccess } from "@/lib/server-supabase";

export async function POST(req: NextRequest) {
  try {
    const notification=await req.json();
    const objectId=notification?.object?.id;
    if(!objectId||typeof objectId!=="string"){
      return NextResponse.json({error:"Invalid notification"},{status:400});
    }

    const payment=await yookassaRequest("/payments/"+encodeURIComponent(objectId));
    if(payment.id!==objectId){
      return NextResponse.json({error:"Payment mismatch"},{status:400});
    }

    if(notification.event==="payment.succeeded"&&payment.status==="succeeded"){
      const access=await grantPaidAccess(payment);
      console.info("EDITA payment succeeded",{paymentId:payment.id,product:payment.metadata?.product,access});
    }

    if(notification.event==="payment.canceled"&&payment.status==="canceled"){
      console.info("EDITA payment canceled",{paymentId:payment.id});
    }

    return NextResponse.json({ok:true});
  } catch(error) {
    console.error("YooKassa webhook error",error);
    return NextResponse.json({error:"Webhook verification failed"},{status:502});
  }
}

import {NextRequest,NextResponse} from "next/server";
import {createHash} from "crypto";

const ACCESS_HASH="bfc66c41fc002c17d37c9649cce339179454851d26591ccae64b489df56ff3e1";

export async function POST(req:NextRequest){
  const body=await req.json().catch(()=>({}));
  const code=String(body?.code||"").trim().toUpperCase();
  const hash=createHash("sha256").update(code).digest("hex");

  if(hash!==ACCESS_HASH){
    return NextResponse.json({error:"Код не подошёл. Проверь символы и попробуй ещё раз."},{status:401});
  }

  const res=NextResponse.json({ok:true});
  res.cookies.set("edita_prelaunch",code,{
    httpOnly:true,
    secure:true,
    sameSite:"lax",
    path:"/",
    maxAge:60*60*24*30
  });
  return res;
}

