 },[viewer.role]);

 useEffect(()=>{
   fetch("/api/ai/health").then(r=>r.json()).then(d=>setAiConfigured(Boolean(d.connected))).catch(()=>setAiConfigured(false));
   try{
     const raw=localStorage.getItem("edita_lesson_done");
